export type AnonymousCargoListingListingType = typeof AnonymousCargoListingListingType[keyof typeof AnonymousCargoListingListingType];


export const AnonymousCargoListingListingType = {
  CARGO: 'CARGO',
} as const;

export type AnonymousCargoListingVisibility = typeof AnonymousCargoListingVisibility[keyof typeof AnonymousCargoListingVisibility];


export const AnonymousCargoListingVisibility = {
  OPEN_NETWORK: 'OPEN_NETWORK',
} as const;

export type AnonymousCargoListingListingStatus = typeof AnonymousCargoListingListingStatus[keyof typeof AnonymousCargoListingListingStatus];


export const AnonymousCargoListingListingStatus = {
  ACTIVE: 'ACTIVE',
} as const;

/**
 * Privacy-safe open-network cargo representation. It intentionally
 * contains bands rather than exact tonnage, timestamps, coordinates, or
 * owner-entered notes.
 */
export interface AnonymousCargoListing {
  id: string;
  transportMode: TransportMode;
  listingType: AnonymousCargoListingListingType;
  cargoTypeBand: string;
  loadingRegion: string;
  destinationRegion: string;
  requiredVesselType: VesselType;
  /** Anonymized cargo tonnage band, never an exact weight. */
  tonnageBand: string;
  /** Anonymized loading-window band, never exact timestamps. */
  timeBand: string;
  /** Broad approximate positioning band, not a route or sailing distance. */
  distanceBand: string;
  visibility: AnonymousCargoListingVisibility;
  listingStatus: AnonymousCargoListingListingStatus;
  deepseaRequirementsBand?: string;
}

export type AnonymousCapacityListingListingType = typeof AnonymousCapacityListingListingType[keyof typeof AnonymousCapacityListingListingType];


export const AnonymousCapacityListingListingType = {
  CAPACITY: 'CAPACITY',
} as const;

export type AnonymousCapacityListingVisibility = typeof AnonymousCapacityListingVisibility[keyof typeof AnonymousCapacityListingVisibility];


export const AnonymousCapacityListingVisibility = {
  OPEN_NETWORK: 'OPEN_NETWORK',
} as const;

export type AnonymousCapacityListingListingStatus = typeof AnonymousCapacityListingListingStatus[keyof typeof AnonymousCapacityListingListingStatus];


export const AnonymousCapacityListingListingStatus = {
  ACTIVE: 'ACTIVE',
} as const;

export type AnonymousCapacityListingPositioningConfidence = typeof AnonymousCapacityListingPositioningConfidence[keyof typeof AnonymousCapacityListingPositioningConfidence];


export const AnonymousCapacityListingPositioningConfidence = {
  PROVISIONAL: 'PROVISIONAL',
  ESTIMATED: 'ESTIMATED',
} as const;

/**
 * Privacy-safe open-network capacity representation. It intentionally
 * contains bands rather than exact tonnage, timestamps, coordinates,
 * vessel identity, or owner-entered notes.
 */
export interface AnonymousCapacityListing {
  id: string;
  transportMode: TransportMode;
  listingType: AnonymousCapacityListingListingType;
  vesselType: VesselType;
  availabilityType: AvailabilityType;
  cargoCompatibilityBand: string;
  directionBand: string;
  availabilityRegion: string;
  /** Anonymized available-capacity band, never an exact tonnage. */
  tonnageBand: string;
  /** Anonymized availability band, never exact timestamps. */
  timeBand: string;
  /** Anonymized maximum-positioning band, never an exact distance. */
  distanceBand: string;
  visibility: AnonymousCapacityListingVisibility;
  listingStatus: AnonymousCapacityListingListingStatus;
  deepseaClassBand?: string;
  dwtBand?: string;
  availabilityConfidence?: AvailabilityConfidence;
  positioningConfidence?: AnonymousCapacityListingPositioningConfidence;
  /** Deepsea feasibility remains provisional because manual inputs are user-estimated, not verified route data. */
  provisional?: boolean;
}

